[95184] = { en="The Sharpest of Blades", ai=true,
[===[Найгостріший із клинків]===],
[===[Суворі бойові тренування — це одне, але ці новобранці ще не розуміють різниці між мечем для тренувань і доглянутим клинком досвідченого ветерана.

