},
[96084] = { en="Something's in the Water", ai=true,
[===[Щось у воді]===],
[===[Позбавлю тебе моторошних подробиць, але цим солдатам страшенно зле. З характеру їхньої недуги я гадаю, що проблема або в їжі, або у воді.

