tasks = { ["Contaminant eliminated"] = [===[Джерело забруднення знешкоджено]===] },
},
[96125] = { en="In Need of Relief", ai=true,
[===[Потрібна зміна]===],
[===[Тепер, коли левові шкури зібрано, а орків-браконьєрів винищено, я нарешті можу перепочити.

