nil,
},
[96559] = { en="Supply Drop", ai=true,
[===[Скинуті припаси]===],
[===[Кожен гномський пілот-випробувач знає, що, здіймаючись у наше величне небо, треба бути готовим до найгіршого!

Саме тому ми ніколи не вилітаємо з ангара без пілотських наборів для виживання. До них прикріплено маяк, що вмикається сам і передає по радіо наше місцеперебування додому, щойно набір відкриють. Не кажучи вже про те, що він напханий іншими корисними припасами.

Якщо знайдеш той набір, хоч би де він упав, неодмінно одразу відкрий його й бери собі все, що там є. Ти однаково зробиш мені послугу!]===],
[===[Знайдіть пілотський набір для виживання Фенвіка Клацопружа.]===],
nil,
nil,
},
[96602] = { en="More Unstable Magic", ai=true,
[===[Більше нестабільної магії]===],
