[97074] = { en="Learning to Ride", ai=true,
[===[Навчання верхової їзди]===],
[===[Вітаю, {клас:к}! Здається, як {стать:шукач:шукачка} пригод ти вже {стать:набрався:набралася} достатньо досвіду, тож я можу навчити тебе їздити верхи на шаблезубі, звісно, за певну плату.

